(()=>{'use strict';const key='toolbox2-onboarding-seen-v1';let seen=false;try{seen=localStorage.getItem(key)==='yes'}catch{}if(seen)return;const slides=[{k:'YOUR MARITIME COMPANION',h:'Welcome aboard.',p:'Everything you need to prepare for your next voyage, organized in one place.'},{k:'PREPARE WITH CONFIDENCE',h:'Ready ka na bang sumampa?',p:'Keep your voyage checklists, documents and essential preparation within reach.'},{k:'BUILT FOR SEAFARERS',h:'Prepare. Learn. Sail.',p:'Explore Toolbox at your own pace. Your progress stays on this device during testing.'}];const overlay=document.createElement('section');overlay.className='tb-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Toolbox welcome');overlay.innerHTML=`<div class="tb-intro-panel"><div class="tb-intro-top"><div class="tb-intro-brand"><img src="assets/toolbox-icon-192.png" alt=""><span>TOOLBOX</span></div><button type="button" class="tb-intro-skip" id="tbIntroSkip">Skip</button></div><div class="tb-intro-content"><div class="tb-intro-art"><div class="tb-intro-halo"></div><img src="assets/toolbox-spanner.png" alt="Toolbox wrench mascot" onerror="this.src='assets/seafarer-mascot.webp'"></div><div class="tb-intro-kicker" id="tbIntroKicker"></div><h1 id="tbIntroTitle"></h1><p id="tbIntroText"></p></div><div class="tb-intro-actions"><div class="tb-intro-dots" id="tbIntroDots" aria-label="Onboarding progress"></div><button type="button" class="tb-intro-next" id="tbIntroNext"></button><div class="tb-intro-note">Explore without creating an account</div></div></div>`;document.body.appendChild(overlay);let step=0;const $=id=>overlay.querySelector('#'+id);const previous=document.activeElement;function draw(){const s=slides[step];$('tbIntroKicker').textContent=s.k;$('tbIntroTitle').textContent=s.h;$('tbIntroText').textContent=s.p;$('tbIntroDots').innerHTML=slides.map((_,i)=>`<span class="${i===step?'active':''}"></span>`).join('');$('tbIntroNext').textContent=step===slides.length-1?'Open Toolbox':'Continue';$('tbIntroSkip').hidden=step===slides.length-1}function finish(){try{localStorage.setItem(key,'yes')}catch{}overlay.remove();previous?.focus?.()}$('tbIntroNext').addEventListener('click',()=>{if(step<slides.length-1){step++;draw()}else finish()});$('tbIntroSkip').addEventListener('click',finish);overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finish()}if(e.key==='Tab'){const focusable=[...overlay.querySelectorAll('button:not([hidden])')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}});draw();$('tbIntroNext').focus();})();
